# -*- coding: utf-8 -*-
"""
Translations for CG_disc4066 (97 items)
Scene: My Guiding Star (Ngôi Sao Dẫn Lối)
Memory disc: Alina (later Noya) and the protagonist
"""

TRANSLATIONS_CG_DISC4066 = {
    'CG_disc4066.4': 'Mảnh Ghép Ký Ức',
    'CG_disc4066.5': 'Ngôi Sao Dẫn Lối',
    'CG_disc4066.6': 'Để một lần nữa được kề vai bên người ấy, người nữ hiệp sĩ lập lời thề dưới bầu trời đầy sao và tòa tháp cô liêu.',
    'CG_disc4066.46': 'Bên trái, tầm cao!',
    'CG_disc4066.54': 'Bên phải, tầm thấp!',
    'CG_disc4066.61': 'Tốt lắm. Chém dứt khoát xuống. Thả lỏng cổ tay ra một chút, chừa khoảng trống để xoay người.',
    'CG_disc4066.65': 'Khá hơn rồi đấy. Giữ vững trọng tâm nào. Cậu đang nhoài người về phía trước quá nhiều rồi. Phải giữ thăng bằng thì mới đổi bộ pháp linh hoạt được.',
    'CG_disc4066.77': 'T-Thế này hả?',
    'CG_disc4066.78': 'Chính xác. Tư thế của cậu tiến bộ nhiều rồi đấy.',
    'CG_disc4066.81': 'Được rồi, giờ chúng ta thử thực chiến nhé, ==PLAYER_NAME==. Hãy dốc toàn lực áp dụng tất cả những gì vừa học đi. Đừng nương tay đấy.',
    'CG_disc4066.97': 'Tiếng kiếm va chạm vang vọng giòn giã giữa màn đêm tĩnh mịch. Nắm chặt thanh kiếm tập trong tay, tôi dồn toàn bộ sức lực lao vào tấn công.',
    'CG_disc4066.104': 'Một nhát chém cơ bản chắc chắn sẽ bị cô ấy đỡ được ngay. Cô ấy bảo phải dốc toàn lực, vậy thì...',
    'CG_disc4066.107': 'Tôi tới đây, Alina!',
    'CG_disc4066.112': 'Giương đông kích tây, giả vờ chém để tung đòn đâm thẳng',
    'CG_disc4066.129': 'Hửm... Khá đấy chứ.',
    'CG_disc4066.130': 'Mũi kiếm của tôi luồn lách qua thế phòng thủ của cô ấy. Đòn đánh chuẩn xác đầu tiên của tôi trong đêm nay.',
    'CG_disc4066.131': 'Trúng rồi nhé!==W== Khoan đã, cái g—?!',
    'CG_disc4066.157': 'Cái...==W== Chuyện gì vừa xảy ra thế? M-Mình đang nằm bẹp dưới đất ư?',
    'CG_disc4066.161': 'Alina, nương tay chút...==W== Tôi không thở nổi nữa rồi! Tôi xin hàng!',
    'CG_disc4066.163': 'X-Xin lỗi cậu, ==PLAYER_NAME==! Chỉ là phản xạ tự nhiên thôi. Cậu có bị đau ở đâu không?==W== Nào, để tôi đỡ cậu dậy.',
    'CG_disc4066.169': 'Tôi không sao, đừng bận tâm. Vả lại cô cũng đã bảo vệ tôi mà, đúng không? Lúc quật tôi ngã xuống,==W== cô đã kịp giữ lấy vai tôi để giảm lực chấn động rồi.',
    'CG_disc4066.172': 'Mà này, chiêu vừa rồi của tôi cũng ra trò đấy chứ? Tôi thậm chí còn ép được cô phải dùng đòn khóa cơ mà! Trình độ kiếm thuật của tôi hẳn là cũng tiến bộ vượt bậc rồi nhỉ?',
    'CG_disc4066.174': 'Kiếm thuật của cậu...==W== quả thực đã thuần thục hơn nhiều. Đòn hư chiêu giả vờ chém để bất ngờ đâm tới cũng rất khôn ngoan.',
    'CG_disc4066.177': 'Thế nhưng thể lực của cậu lại chưa theo kịp. Cơ thể cậu đơn giản là không đuổi kịp suy nghĩ trong đầu. Khoảnh khắc cậu chuyển bộ pháp, cậu đã để lộ ra một sơ hở chết người.',
    'CG_disc4066.180': 'Một sơ hở chí mạng đến mức...==W== khiến đối thủ theo bản năng chỉ muốn áp sát ngay lập tức, gạt chân cậu rồi giáng thẳng một cú thiết đầu công vào mặt.',
    'CG_disc4066.185': 'Cám dỗ đó lớn quá. Cơ thể tôi tự động phản xạ mất rồi. Cũng may là tôi đã kịp kìm lại trước khi tung cú húc đầu đấy.',
    'CG_disc4066.187': 'Khoan đã. Hóa ra cô túm lấy tôi không phải để đỡ tôi khỏi ngã... mà là đang kéo tôi lại gần để húc gãy mũi tôi sao?!',
    'CG_disc4066.190': 'Này này, thế có tàn bạo quá không hả?! Chúng ta đang tập luyện thôi mà!',
    'CG_disc4066.192': 'Khụ. Đó là lỗi của tôi. Nhưng nếu luyện tập mà không dốc hết sức, cậu sẽ chẳng trụ nổi nửa giây trong thực chiến đâu.',
    'CG_disc4066.193': 'Chính cậu cũng cảm nhận được rồi, đúng không ==PLAYER_NAME==? Cơ thể cậu đang kìm hãm phản xạ của bộ não. Chiến thuật có hay đến mấy cũng trở nên vô nghĩa==W== nếu cậu không đủ sức thực hiện nó.',
    'CG_disc4066.194': 'Nhưng rèn luyện thể lực không phải chuyện một sớm một chiều. Dù có luyện tập mỗi ngày thì cũng phải mất nhiều tháng mới thấy được kết quả rõ rệt.',
    'CG_disc4066.196': 'Bắt đầu từ ngày mai, hãy chạy bộ đêm cùng tôi nhé. Chúng ta sẽ kết hợp rèn luyện sức bền song song với luyện tập kiếm chiêu. Cứ kiên trì từng bước một, rồi mọi thứ sẽ dần tiến bộ thôi.',
    'CG_disc4066.197': 'Rõ rồi, rõ rồi mà. Tôi sẽ luyện tập nghiêm túc.',
    'CG_disc4066.198': 'Cơ mà cứ hễ nhắc đến chuyện đao kiếm là cô lại thao thao bất tuyệt chẳng muốn dừng lại nhỉ.',
    'CG_disc4066.200': 'Hả—? T-Tôi sao? Tôi nhiều lời đến thế thật ư?',
    'CG_disc4066.202': 'Nghĩ lại thì, trong toàn bộ thời gian hai chúng ta ở riêng bên nhau, chắc phải đến năm mươi phần trăm là vùi đầu vào luyện kiếm...',
    'CG_disc4066.203': 'Đ-Đâu có đúng!==W== Chúng ta còn cùng nhau đi tuần tra nữa cơ mà... Nhắc mới nhớ, giờ chúng ta đi tuần tra luôn đi! Đổi gió một chút sẽ tốt cho cậu đấy.',
    'CG_disc4066.205': 'Và năm mươi phần trăm còn lại chính là đi tuần tra.',
    'CG_disc4066.206': 'Ừm. Câu này thì tôi chịu chết, chẳng cãi vào đâu được.',
    'CG_disc4066.208': 'Tôi rất ngại phải thừa nhận, nhưng cuộc sống của tôi đúng là...==W== đơn điệu thật. Đi cùng một người như tôi hẳn là tẻ nhạt lắm phải không, ==PLAYER_NAME==.',
    'CG_disc4066.211': 'Xét một cách khách quan ư? Đúng là hơi tẻ nhạt thật.==W== Nhưng được làm những việc đó cùng cô thì tất cả đều xứng đáng.',
    'CG_disc4066.213': 'Thật sao?==W== Nhưng mà... tôi đâu có gì thú vị. Tôi chẳng sắc sảo hay hiểu rộng biết nhiều như Elis, lại càng chẳng thông thuộc Filanis bằng một nửa của Lulu.',
    'CG_disc4066.215': 'Chỉ cần ở bên cạnh cô thôi là tôi đã cảm thấy an tâm rồi.',
    'CG_disc4066.216': 'A...==W== An tâm ư?',
    'CG_disc4066.218': 'Kiếm thuật của tôi đúng là khá, và tôi sẽ luôn bảo vệ cậu. Nhưng tôi đâu thể giải quyết được mọi rắc rối trên đời.',
    'CG_disc4066.219': 'Ngay cả khi tuần tra trong một thành phố "hoàn hảo" như Filanis, chúng ta vẫn có thể chạm trán một tên trộm đang chết đói, hay một gã côn đồ hung hãn từ thành phố khác tới.',
    'CG_disc4066.220': 'C-Cậu tuyệt đối không được mất cảnh giác chỉ vì có tôi ở bên cạnh đâu đấy! Cậu không thể cứ vô tư cảm thấy an tâm như thế được. Lỡ chúng ta bị mai phục thì sao?',
    'CG_disc4066.221': 'Nói một cách nghiêm túc thì tôi không thể bảo đảm an toàn cho cậu trong mọi tình huống có thể xảy ra được đâu. Thế nên...==W== Xin cậu đừng lơ là cảnh giác nhé.',
    'CG_disc4066.222': 'Ý tôi an tâm không phải là kiểu an toàn đó. Ý tôi là...==W== Ngay cả khi chúng ta bước đi trong bóng tối, và dù cho ở đây hầu như chẳng ai hay biết những gì cô đã hy sinh vì họ...',
    'CG_disc4066.223': '... Cô chưa từng một lần nản lòng thoái chí. Và cô chưa bao giờ ngừng nỗ lực vì một ngày mai tốt đẹp hơn.',
    'CG_disc4066.225': 'Cô giống như một vầng thái dương nhỏ bé ấm áp vậy. Chỉ cần ở bên cạnh cô thôi, ngọn lửa nhiệt huyết trong tôi cũng được thắp sáng theo.',
    'CG_disc4066.226': 'Phù. Tôi cũng phải cố gắng nhiều hơn nữa thôi. Khi cô tìm được cách trở lại Cự Thạch, tôi cũng sẽ tìm con đường để trở về nhà.',
    'CG_disc4066.232': 'Nhà của cậu ư...==W== Cậu có thể kể thêm cho tôi nghe về nơi đó không?',
    'CG_disc4066.233': 'Trước đây cậu từng nói ở đó không có chế độ nô lệ...==W== Đó là một thành phố như thế nào vậy?',
    'CG_disc4066.234': 'À, nhà của tôi thực ra không hẳn là một thành phố. Đó là một cỗ xe.',
    'CG_disc4066.235': 'Tôi cùng bạn bè rong ruổi trên cỗ xe ấy đi khắp thế gian. Nhưng đúng là trong tất cả những nơi chúng tôi từng đi qua, chẳng nơi nào có nô lệ cả.',
    'CG_disc4066.236': 'Nghe có vẻ...==W== thật tự do biết bao. Từ thuở ấu thơ đến giờ, những nơi duy nhất tôi từng biết đến chỉ có Đại Đấu Trường ở Emor và thành phố Filanis này.',
    'CG_disc4066.238': 'Tôi thậm chí còn chẳng biết...==W== bên ngoài những bức tường của Đấu Trường thì Emor trông ra sao nữa.',
    'CG_disc4066.239': 'Rồi cô sẽ có cơ hội thôi mà. Bây giờ cô cũng đã tự do rồi, Alina. Cô ở lại đây chỉ là để báo đáp ân tình, và chung tay biến Filanis thành một nơi tốt đẹp hơn thôi.',
    'CG_disc4066.243': 'Một ngày nào đó, Filanis sẽ trở thành thành phố trong mơ như cô hằng mong ước. Khi ngày đó đến...==W== nếu tôi vẫn còn ở đây, chúng ta sẽ cùng nhau đi du ngoạn khắp chân trời góc bể nhé.',
    'CG_disc4066.245': 'Đó là một lời hứa chứ?',
    'CG_disc4066.246': 'Đó là một lời hứa.',
    'CG_disc4066.247': 'A, nhìn đồng hồ kìa. Tôi phải bắt đầu chuyến tuần tra và thổi tù và báo giờ rồi.',
    'CG_disc4066.248': 'Tôi đi cùng cô.',
    'CG_disc4066.249': 'Đêm qua cậu đã thức khuya ghi chép sổ sách cho Đội Tuần Đêm rồi...==W== Giờ cậu còn mở nổi mắt ra không đấy?',
    'CG_disc4066.252': 'Đừng coi thường tôi chứ. Tôi là cú đêm chính hiệu đấy.',
    'CG_disc4066.260': 'Rốt cuộc thì vẫn ngủ say như chết rồi này. Đang đi giữa đường mà cậu cũng gật gù thiếp đi được, tay vẫn còn bám chặt lấy chuôi kiếm của tôi nữa chứ.',
    'CG_disc4066.261': 'Dạo này cậu đã gắng gượng quá nhiều rồi đấy, ==PLAYER_NAME==.',
    'CG_disc4066.266': 'Alina bế bổng lấy ==SEX9== đang tựa người vào cô, đẩy cánh cửa của gian phòng insula rồi nhẹ nhàng đặt ==SEX4== xuống giường.',
    'CG_disc4066.272': '<size=85%>Ở bên cạnh tôi...</size>==W==<size=85%> thực sự khiến cậu an lòng đến thế sao?</size>',
    'CG_disc4066.273': '<size=85%>Nói thật lòng thì...</size>==W==<size=85%> Được ở bên cạnh cậu, tôi cũng cảm thấy thật bình yên.</size>',
    'CG_disc4066.274': '<size=85%>Nhất là...</size>==W==<size=85%> mỗi khi ngắm nhìn gương mặt say ngủ của cậu.</size>',
    'CG_disc4066.277': 'Chuyến tuần đêm khép lại. Alina ngồi xuống, tựa lưng vào mép giường.',
    'CG_disc4066.278': 'Dưới ánh sao đêm lạnh giá, hơi thở êm dịu của hai người hòa chung nhịp đập khi họ cùng chìm sâu vào giấc ngủ.',
    'CG_disc4066.287': 'Một khoảng thời gian sau, người nữ hiệp sĩ bừng tỉnh giấc.',
    'CG_disc4066.288': 'Chiếc giường giờ đây trống trải. Gối và chăn được xếp gọn gàng ngăn nắp, như thể luôn sẵn sàng chào đón một lữ khách phong trần mệt mỏi ghé bước nghỉ ngơi.',
    'CG_disc4066.289': 'Người nữ hiệp sĩ chưa từng một lần nằm lên giường. Cô đã quen với việc chợp mắt tựa vào mép giường rồi. Chiếc giường ấy...==W== chỉ dành riêng cho một người. Một người vô cùng quan trọng đối với cô.',
    'CG_disc4066.291': 'Người nữ hiệp sĩ cầm lấy thanh trường kiếm và bước ra khỏi gian phòng insula chật hẹp, đắm mình trong ánh sao lạnh lẽo.',
    'CG_disc4066.295': 'Thành phố Filanis ngày nay đã không còn cần đến những chuyến tuần đêm của cô nữa rồi.',
    'CG_disc4066.296': 'Những công dân trẻ tuổi đã gia nhập Đội Tuần Đêm, thay phiên nhau túc trực mỗi ngày để bảo vệ thành phố thuộc về chính họ.',
    'CG_disc4066.297': 'Thế nhưng theo thói quen, cô vẫn bước ra khỏi nhà vào giờ này, đi đến khoảng sân trống bên cạnh gian phòng insula.',
    'CG_disc4066.301': 'Ánh mắt cô vô định tìm kiếm. Cô mải miết dõi theo một bóng hình, chờ đợi một thanh âm thân quen cất tiếng gọi tên mình.',
    'CG_disc4066.302': 'Thế nhưng một tiếng cười khẽ bật ra từ khóe môi cô đã phá tan ảo mộng ấy.',
    'CG_disc4066.303': 'Giờ đây cô không còn là Alina nữa. Cô là Noya, một tồn tại nhỏ bé không tên.',
    'CG_disc4066.304': 'Một Noya mong muốn trở thành người mà ==PLAYER_NAME== từng nhắc tới...==W== Một Noya mà ngay cả ==PLAYER_NAME== cũng chưa từng biết đến.',
    'CG_disc4066.305': 'Haizz... Mình ngốc nghếch thật đấy.',
    'CG_disc4066.308': 'Mình còn đứng đây tìm kiếm điều gì nữa chứ? ==SEX1== đang ở ngay đằng kia rồi, bên trong Cự Thạch.',
    'CG_disc4066.317': 'Người nữ hiệp sĩ khẽ thì thầm với chính mình, chậm rãi giơ thanh trường kiếm vào thế thủ, tựa như người bạn đồng hành với đầu óc nhiều mưu mẹo hơn là kiếm thuật vẫn đang đứng sờ sờ ngay trước mắt.',
    'CG_disc4066.318': 'Tôi nhất định sẽ bảo vệ tương lai mà cậu đã mang lại cho chúng tôi. Mãi mãi.',
    'CG_disc4066.319': 'Tôi sẽ bảo đảm những dấu ấn cậu để lại trên mảnh đất Filanis này sẽ trường tồn theo năm tháng.==W== Cho đến ngày cậu thực hiện lời hứa giữa hai chúng ta.',
    'CG_disc4066.320': 'Đúng vậy. Chỉ cần tôi kiên trì bền bỉ, mọi chuyện rồi sẽ ổn thỏa. Mọi ước nguyện đều sẽ trở thành hiện thực.',
    'CG_disc4066.323': 'Tôi không hề hối tiếc điều gì cả, ==PLAYER_NAME==. Và tôi tin chắc rằng cậu cũng như vậy.',
    'CG_disc4066.325': 'Hãy dõi theo tôi nhé. Tôi nhất định sẽ trở nên mạnh mẽ hơn nữa.',
    'CG_disc4066.326': 'Lần tới tao ngộ, tôi nhất định sẽ bảo vệ cậu đến giây phút cuối cùng. Vì vậy xin người... hãy cho tôi gửi gắm một nguyện ước.',
    'CG_disc4066.328': 'Nguyện ước một ngày nào đó... hai ta sẽ lại được tương phùng.',
    'CG_disc4066.331': 'Người nữ hiệp sĩ giương cao thanh kiếm lập lời thề trước bầu trời đêm. Giữa chốn hoang vu này,==RT==những người duy nhất lắng nghe tâm nguyện của cô chỉ có muôn triệu vì sao trên cao và tòa tháp cô tịch.',
    'CG_disc4066.332': 'Còn về việc liệu ước nguyện ấy có thành hiện thực hay không... Đó sẽ là câu chuyện thuộc về một thời đại khác.',
}
